import{_ as o,C as n,o as s,c as e,j as i,E as l,a as r,a3 as d}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/mentor/10-sinf-devops/"},"n":3,"bob":"II-bob · Git va versiya boshqaruvi","lessons":[{"g":7,"title":"Git branchlar va masofaviy repozitoriylar (GitHub, Push, Pull, Merge)","lead":"Jamoaviy dasturlash san'ati: parallel rivojlanish tarmoqlari (branches), birlashtirish (merge), ziddiyatlarni yechish hamda GitHub orqali masofaviy hamkorlik.","link":"/mentor/10-sinf-devops/hafta-03/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-1-test.html"},{"g":8,"title":"Kompyuter tarmoqlari asoslari: OSI 7 qatlamli modeli va TCP/IP steki","lead":"Internet qanday ishlaydi: LAN va WAN tarmoqlari, OSI 7 qatlamli etalon modeli, amaliy TCP/IP steki va ma'lumotlar sayohati (enkapsulyatsiya).","link":"/mentor/10-sinf-devops/hafta-03/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-2-test.html"},{"g":9,"title":"IP manzillash, Subnetting va tarmoq diagnostikasi vositalari","lead":"Tarmoq muhandisligi asoslari: IPv4 va IPv6, qism tarmoqlarni hisoblash (Subnetting, CIDR) hamda nosozliklarni aniqlovchi qurollar (ping, traceroute, ss, curl).","link":"/mentor/10-sinf-devops/hafta-03/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/10-sinf-devops/hafta-03/index.md","filePath":"mentor/10-sinf-devops/hafta-03/index.md"}`),h={name:"mentor/10-sinf-devops/hafta-03/index.md"},m={class:"blk"},c={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},g={id:"baholash-mezoni",tabindex:"-1"};function v(b,a,q,f,y,k){const t=n("Icon");return s(),e("div",null,[i("div",m,[i("h2",c,[l(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>3-haftada Git versiya boshqaruvi tizimining ilg&#39;or mexanizmlari (tarmoqlanish, birlashtirish, ziddiyatlarni hal qilish va masofaviy repozitoriyalar) hamda kompyuter tarmoqlarining fundamental asoslari (OSI modeli, TCP/IP steki, IP manzillash, Subnetting va tarmoq diagnostikasi) o&#39;rganildi. Quyidagi amaliy topshiriqlar bilimlarni sinovdan o&#39;tkazishga qaratilgan.</p><hr><h2 id="_7-dars-vazifasi-git-branchlar-va-birlashtirish" tabindex="-1">7-dars vazifasi: Git Branchlar va Birlashtirish <a class="header-anchor" href="#_7-dars-vazifasi-git-branchlar-va-birlashtirish" aria-label="Permalink to &quot;7-dars vazifasi: Git Branchlar va Birlashtirish&quot;">​</a></h2><ol><li>O&#39;tgan haftadagi <code>my_git_lab</code> repozitoriyasida <code>feature-auth</code> nomli yangi branch oching (<code>git switch -c feature-auth</code>).</li><li>Yangi branch ichida <code>auth.py</code> faylini yaratib, ichiga oddiy login kodini yozing va <code>git commit -m &quot;feat: login funksiyasi qo&#39;shildi&quot;</code> bilan commit qiling.</li><li>Asosiy <code>main</code> branchga qayting (<code>git switch main</code>).</li><li><code>feature-auth</code> branchini <code>main</code> ga birlashtiring (<code>git merge feature-auth</code>).</li><li>Birlashtirilgan branchni xavfsiz o&#39;chiring (<code>git branch -d feature-auth</code>).</li><li><code>git log --oneline --graph</code> buyrug&#39;i natijasini daftaringizga qayd eting. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_8-dars-vazifasi-tarmoq-qatlamlari-va-interfeyslar-tahlili" tabindex="-1">8-dars vazifasi: Tarmoq qatlamlari va Interfeyslar tahlili <a class="header-anchor" href="#_8-dars-vazifasi-tarmoq-qatlamlari-va-interfeyslar-tahlili" aria-label="Permalink to &quot;8-dars vazifasi: Tarmoq qatlamlari va Interfeyslar tahlili&quot;">​</a></h2><ol><li>Linux terminalida <code>ip a</code> buyrug&#39;ini ishga tushiring. Tizimingizdagi jismoniy tarmoq kartasining nomi, uning MAC manzili va lokal IP manzilini aniqlab daftaringizga ko&#39;chirib yozing.</li><li><code>ip route</code> buyrug&#39;i yordamida tashqi dunyoga chiquvchi Default Gateway (Router) IP manzilini toping.</li><li>OSI 7 qatlamli modelining har bir qatlami nomini (1 dan 7 gacha) va har bir qatlamda ishlovchi kamida bittadan protokolni jadval ko&#39;rinishida daftaringizga chizing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h2 id="_9-dars-vazifasi-subnetting-va-tarmoq-diagnostikasi" tabindex="-1">9-dars vazifasi: Subnetting va Tarmoq diagnostikasi <a class="header-anchor" href="#_9-dars-vazifasi-subnetting-va-tarmoq-diagnostikasi" aria-label="Permalink to &quot;9-dars vazifasi: Subnetting va Tarmoq diagnostikasi&quot;">​</a></h2><ol><li><code>ping -c 4 8.8.8.8</code> buyrug&#39;i orqali Google DNS serveriga so&#39;rov yuboring. O&#39;rtacha kechikish (rtt avg) va paketlar yo&#39;qolish foizini daftaringizga qayd eting.</li><li><code>curl ifconfig.me</code> buyrug&#39;i yordamida uyingizning tashqi ommaviy (Public) IP manzilini aniqlang.</li><li><code>curl -I https://yandex.uz</code> buyrug&#39;ini berib, HTTP javob kodini aniqlang.</li><li>Quyidagi hisoblash masalasini yeching: <ul><li>Berilgan: <code>192.168.100.0/25</code> tarmog&#39;i.</li><li>Aniqlang: a) Tarmoq maskasi (Subnet Mask) b) Foydalanish mumkin bo&#39;lgan maksimal xostlar soni c) Tarmoq manzili (Network ID) d) Efir manzili (Broadcast ID) <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ul></li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><ul><li><strong>Tekshirish mezonlari:</strong><ol><li>O&#39;quvchi branch ochish (<code>git switch -c</code>), kommit qilish va <code>merge</code> qilish ketma-ketligini to&#39;g&#39;ri bajarganmi.</li><li>OSI 7 qatlamli modeli va TCP/IP steki o&#39;rtasidagi mantiqiy bog&#39;liqlikni tushunganmi.</li><li>MAC va IP manzil farqini ajrata oladimi (2-qatlam vs 3-qatlam).</li><li>Subnetting formulasidan ($2^H - 2$) to&#39;g&#39;ri foydalanib, xostlar soni va tarmoq parametrlarini to&#39;g&#39;ri hisoblaganmi.</li><li><code>ping</code> va <code>curl</code> buyruqlari natijalarini to&#39;g&#39;ri tahlil qila oladimi.</li></ol></li><li><strong>Tez-tez uchraydigan xatolar:</strong><ul><li>Branch birlashtirishda <code>main</code> ga o&#39;tishni unutib, yangi branch ichida turib merge qilish.</li><li>Subnet hisoblashda 2 ta zaxira manzilni (Network ID va Broadcast ID) ayirishni unutish ($2^H$ o&#39;rniga $2^H - 2$).</li><li>Ommaviy va xususiy IP farqini tushunmaslik (<code>192.168.x.x</code> manzilini global Internetda izlash).</li></ul></li></ul>',13))]),i("div",u,[i("h2",g,[l(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p><strong>Mavzular:</strong></p><ol><li>Git bilan ishlash (2-qism): Branchlar, merge, mojarolar (conflict resolution) va GitHub (push, pull, clone)</li><li>Kompyuter tarmoqlari asoslari: LAN/WAN, tarmoq uskunalari, OSI 7 qatlamli modeli va TCP/IP steki, enkapsulyatsiya</li><li>IP manzillash va tarmoq diagnostikasi: IPv4/IPv6, RFC 1918 xususiy tarmoqlar, Subnetting/CIDR, ping, traceroute, ss, curl</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Git Branch va GitHub</strong></td><td>Tarmoqlar yaratish (branch/switch), fast-forward va 3-way merge, mojarolarni yechish, masofaviy repozitoriy (remote/push/pull)</td><td>30 ball</td></tr><tr><td><strong>Tarmoq va OSI/TCP-IP</strong></td><td>Tarmoq topologiyalari, Switch va Router farqlari, OSI 7 qatlami vazifalari, enkapsulyatsiya/dekapsulyatsiya bosqichlari</td><td>30 ball</td></tr><tr><td><strong>IP Manzillash va Diagnostika</strong></td><td>IPv4 sinflari, RFC 1918 xususiy diapazonlari, CIDR prefiksi va maska hisoblash, ping, traceroute, ss, curl diagnostik buyruqlari</td><td>40 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Git Branch (30)</th><th>OSI &amp; TCP/IP (30)</th><th>IP &amp; Diagnostika (40)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar Git&#39;da merge conflict chiqqanda mojaroli belgilarni (<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>, <code>=======</code>, <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>) qo&#39;lda to&#39;g&#39;irlab, qayta <code>git add</code> va <code>git commit</code> qilish tartibini unutib qo&#39;yishlari mumkin. Tarmoq mavzusida esa Subnetting (masalan, <code>/26</code> prefiksida nechta IP bo&#39;lishi va tarmoq/broadcast manzillarini ajratish) qo&#39;shimcha amaliy hisoblashni talab qiladi.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> GitHub Pull Request jarayonini sinfdoshlari bilan juftlikda sinab ko&#39;rish yoki <code>curl -Iv</code> orqali HTTPS handshake va HTTP javob headerlarini to&#39;liq tahlil qilish topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const I=o(h,[["render",v]]);export{p as __pageData,I as default};
